def run_program(lines):
    stack = []
    out = []
    for line in lines:
        parts = line.split()
        op = parts[0]
        if op == "PUSH":
            stack.append(int(parts[1]))
        elif op in ("ADD", "SUB", "MUL"):
            top = stack.pop()
            below = stack.pop()
            if op == "ADD":
                stack.append(below + top)
            elif op == "SUB":
                stack.append(below - top)
            else:
                stack.append(below * top)
        elif op == "DUP":
            stack.append(stack[-1])
        elif op == "SWAP":
            stack[-1], stack[-2] = stack[-2], stack[-1]
        elif op == "PRINT":
            out.append(stack.pop())
    return out

